from ocean.drone import *

# File: reef_hurdles.py
# ---------------------
# Cross the bay from left to right, climbing over each reef.
# The bay is 9 squares wide, so the drone crosses 8 gaps.


def turn_right():
    turn_left()
    turn_left()
    turn_left()


# Pre-condition:  facing east, at the bottom of a reef
# Post-condition: facing east, at the bottom, on the other side
def jump_reef():
    climb_up()
    swim_over()
    climb_down()


def climb_up():
    turn_left()
    while right_is_blocked():
        move()
    turn_right()


def swim_over():
    move()


def climb_down():
    turn_right()
    while front_is_clear():
        move()
    turn_left()


def main():
    for i in range(8):
        if front_is_clear():
            move()
        else:
            jump_reef()


if __name__ == '__main__':
    main()
